#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int x;
    struct Node *next;
} Node;

Node *new_node(int x) {
    Node *p = (Node *)malloc(sizeof(Node));
    if (p == NULL) {
        return NULL;
    }
    p->x = x;
    p->next = NULL;
    return p;
}

Node *push_back(Node *head, int x) {
    Node *p = new_node(x);
    if (p == NULL) {
        return head;
    }
    if (head == NULL) {
        return p;
    }
    Node *cur = head;
    while (cur->next != NULL) {
        cur = cur->next;
    }
    cur->next = p;
    return head;
}

Node *remove_value(Node *head, int x, int *found) {
    Node *cur = head;
    Node *prev = NULL;
    *found = 0;
    while (cur != NULL) {
        if (cur->x == x) {
            if (prev == NULL) {
                head = cur->next;
            } else {
                prev->next = cur->next;
            }
            free(cur);
            *found = 1;
            return head;
        }
        prev = cur;
        cur = cur->next;
    }
    return head;
}

void print_list(Node *head) {
    Node *cur = head;
    while (cur != NULL) {
        printf("%d -> ", cur->x);
        cur = cur->next;
    }
    printf("NULL\n");
}

void free_list(Node *head) {
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        free(cur);
        cur = next;
    }
}

int main(void) {
    int x;
    int n;
    if (scanf("%d", &x) != 1) {
        return 1;
    }
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    Node *head = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) {
            return 1;
        }
        head = push_back(head, v);
    }

    int found = 0;
    head = remove_value(head, x, &found);

    printf("摘 %d（%s）：", x, found ? "摘到了" : "没找到");
    print_list(head);

    free_list(head);
    head = NULL;
    return 0;
}
